        dp[1][h(p)] = curr;
        curr++;
    }
    curr--;
    for(int p = lowb+1; p<= lowb+2*k; p++){
        curr--;
        dp[1][h(p)] = curr;
    }
    lowb -=2*k;
    highb+=2*k;
    for(int ti = 1; ti <= t-1; ti++){
        int o = ti%2;
