            sum = (sum+MOD)%MOD;
            dp[!o][h(np)] = sum;
        }

        //slide into those dm's
        while(r<highb){
            //update
            pe++;
            r++;
            l++;
            ir++;
            il++;
            np++;

            long long sum1 = pref[pe-1] - ( (il==1) ? 0 : pref[(il-1)-1]);
            long long sum2 = pref[ir] - pref[pe-1];
            sum = (sum - sum1 + MOD)%MOD;
            sum = (sum + sum2)%MOD;
            dp[!o][h(np)] = sum;
        }
        //finally, suffix
        while(l<highb){
            l++;
            il++;
            pe++;
            np++;
            //subtract [l-1,pe-1]
            long long sum1 = pref[min(pe-1,ir)] - ((il==1) ? 0 : pref[il-1-1]);
            sum = (sum - sum1 + MOD)%MOD;
            if(pe>ir){

            }
            else{
                long long sum2 = pref[ir]-pref[pe-1];
                sum = (sum + sum2)%MOD;
            }
            dp[!o][h(np)] = sum;
        }

        lowb-=2*k;
        highb+=2*k;
    }
    long long ans = 0;
    int o = t%2;
    for(int p = 1; p <= highb; p++){
        ans = (ans+dp[o][h(p)])%MOD;
